proc stepEncLcnAppRuntime*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnAppRuntime](src)
  var n = 1
  if x.apply_deadline_ms.isSome:
    inc n
  if x.endpoint_dir.isSome:
    inc n
  if x.max_payload_depth.isSome:
    inc n
  if x.runtime_instance_id.isSome:
    inc n
  if x.shutdown_grace_ms.isSome:
    inc n
  if x.startup_deadline_ms.isSome:
    inc n
  if x.state_root.isSome:
    inc n
  if x.stop_deadline_ms.isSome:
    inc n
  if x.store_dir.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.apply_deadline_ms.isSome:
    node.entries[k].key = cbor("apply_deadline_ms")
    node.entries[k].value = cbor(uint64(x.apply_deadline_ms.get))
    inc k
  if x.endpoint_dir.isSome:
    node.entries[k].key = cbor("endpoint_dir")
    node.entries[k].value = encLcnAppPath(x.endpoint_dir.get)
    inc k
  if x.max_payload_depth.isSome:
    node.entries[k].key = cbor("max_payload_depth")
    node.entries[k].value = cbor(uint64(x.max_payload_depth.get))
    inc k
  if x.runtime_instance_id.isSome:
    node.entries[k].key = cbor("runtime_instance_id")
    node.entries[k].value = cbor(x.runtime_instance_id.get)
    inc k
  if x.shutdown_grace_ms.isSome:
    node.entries[k].key = cbor("shutdown_grace_ms")
    node.entries[k].value = cbor(uint64(x.shutdown_grace_ms.get))
    inc k
  if x.startup_deadline_ms.isSome:
    node.entries[k].key = cbor("startup_deadline_ms")
    node.entries[k].value = cbor(uint64(x.startup_deadline_ms.get))
    inc k
  if x.state_root.isSome:
    node.entries[k].key = cbor("state_root")
    node.entries[k].value = encLcnAppPath(x.state_root.get)
    inc k
  if x.stop_deadline_ms.isSome:
    node.entries[k].key = cbor("stop_deadline_ms")
    node.entries[k].value = cbor(uint64(x.stop_deadline_ms.get))
    inc k
  if x.store_dir.isSome:
    node.entries[k].key = cbor("store_dir")
    node.entries[k].value = encLcnAppPath(x.store_dir.get)
    inc k
  node.entries[k].key = cbor("work_dir")
  node.entries[k].value = encLcnAppPath(x.work_dir)
  inc k

proc stepDecLcnAppRuntime*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnAppRuntime](dst)
  r[] = LcnAppRuntime()
  let f160 = v.lookup("apply_deadline_ms")
  if f160.isSome:
    r.apply_deadline_ms = Opt.some(uint32(f160.get.uint))
  let f161 = v.lookup("endpoint_dir")
  if f161.isSome:
    r.endpoint_dir = Opt.some(decLcnAppPath(f161.get))
  let f162 = v.lookup("max_payload_depth")
  if f162.isSome:
    r.max_payload_depth = Opt.some(uint16(f162.get.uint))
  let f163 = v.lookup("runtime_instance_id")
  if f163.isSome:
    r.runtime_instance_id = Opt.some(f163.get.text)
  let f164 = v.lookup("shutdown_grace_ms")
  if f164.isSome:
    r.shutdown_grace_ms = Opt.some(uint32(f164.get.uint))
  let f165 = v.lookup("startup_deadline_ms")
  if f165.isSome:
    r.startup_deadline_ms = Opt.some(uint32(f165.get.uint))
  let f166 = v.lookup("state_root")
  if f166.isSome:
    r.state_root = Opt.some(decLcnAppPath(f166.get))
  let f167 = v.lookup("stop_deadline_ms")
  if f167.isSome:
    r.stop_deadline_ms = Opt.some(uint32(f167.get.uint))
  let f168 = v.lookup("store_dir")
  if f168.isSome:
    r.store_dir = Opt.some(decLcnAppPath(f168.get))
  r.work_dir = decLcnAppPath(v.lookup("work_dir").get)

